import sys
import math

def min_final_health(N, A):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    total_gcd = A[0]
    for health in A[1:]:
        total_gcd = gcd(total_gcd, health)

    return total_gcd

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:N+1]))

    result = min_final_health(N, A)
    print(result)

if __name__ == "__main__":
    main()

